window.kbPageData["views/entry/k-a100248ad008d20a"] = {"key":"entry/k-a100248ad008d20a","state":{"route":"entry/k-a100248ad008d20a"},"node":{"id":"k-a100248ad008d20a","mode":"k","title":"帝王讳名制","type":"制度与规则","domain":"历史","reading":"","intro":"","priority":100,"aliases":["帝王讳名制：避用在位帝王的名讳"],"qs":["江苏 2024 A类 行测#93"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"帝王讳名制是古代避讳制度的一种。在规则适用的场合，用字者须避用帝王的名讳，可通过改用其他字来避讳。","review":{"definition":"帝王讳名制是古代避讳制度的一种。在规则适用的场合，用字者须避用帝王的名讳，可通过改用其他字来避讳。","explanation":"学者以帛书《道德经》保留刘恒名中的“恒”字，而传世本写作“常”为线索，推测帛书早于刘恒在位时期。D项以秦代避讳已扩至社会、汉朝继承秦制为依据，增强了避讳可能适用于当时文本的判断。两句同义只说明换字后文义可以相同，保留“恒”也只能为断代提供间接支持。","references":[],"evidence":"帝王讳名制在秦朝从宗族内部扩展到社会整体，汉朝继承了秦朝的许多制度","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 A类 行测#93":{"paper":"江苏 2024 A类 行测","n":93,"mod":"判断推理","src":["f8fec75f67d6d1ba5759.pdf",19],"asrc":["0126a1c8aceee632ea2b.pdf",29],"card":"fdb92199e96c4faf6e5d373d","links":[{"id":"k-a100248ad008d20a","role":"解题依据","why":"在讳名规则可能适用的前提下，保留名讳用字才具有辅助断代的意义。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-a100248ad008d20a":[["江苏 2024 A类 行测#93"]]}};
